function photoId(){if(globalThis.crypto.randomUUID)return crypto.randomUUID();const b=crypto.getRandomValues(new Uint8Array(16));b[6]=(b[6]&15)|64;b[8]=(b[8]&63)|128;const h=Array.from(b,v=>v.toString(16).padStart(2,'0')).join('');return h.slice(0,8)+'-'+h.slice(8,12)+'-'+h.slice(12,16)+'-'+h.slice(16,20)+'-'+h.slice(20)}
export async function photoRequest(cloud,payload){if(!cloud)throw Error('请登录后保存照片');const r=await fetch('/api/photos',{method:payload?'POST':'GET',headers:payload?{'Content-Type':'application/json','X-CSRF-Token':cloud.session.csrf,'X-Planet-Space':String(cloud.session.space)}:{},body:payload?JSON.stringify(payload):undefined});const d=await r.json();if(!r.ok)throw Error(d.error||'照片暂未保存');return d}
const cameraIcon='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" aria-hidden="true"><path d="M8 6l1.5-2h5L16 6h3a2 2 0 0 1 2 2v10a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V8a2 2 0 0 1 2-2z"/><circle cx="12" cy="12.5" r="4"/></svg>';
export function createPhotoUI({visual,cloud,toast,onAlbum}){
 const el=document.createElement('div');el.id='photo-camera';el.innerHTML='<button class="photo-shutter" aria-label="打开相机">'+cameraIcon+'</button><div class="photo-controls" hidden><button data-photo="exit" class="photo-exit" aria-label="退出拍照">×</button><div class="photo-tools"><button data-photo="timer" aria-label="三秒倒计时" aria-pressed="false">3s</button><button data-photo="poses" aria-label="选择姿势">姿势</button></div><div class="photo-poses" hidden>'+[['current','此刻'],['wave','挥手'],['heart','比心'],['chin','托腮']].map(([id,name])=>'<button data-pose="'+id+'">'+name+'</button>').join('')+'</div><output class="photo-count"></output><button class="photo-thumb" hidden aria-label="查看相册"><img alt="刚拍的照片"></button><div class="photo-retry" hidden><button data-photo="retry">重试保存</button><a download="阿球照片.jpg">下载照片</a></div></div>';document.body.append(el);
 const shutter=el.querySelector('.photo-shutter'),controls=el.querySelector('.photo-controls'),poses=el.querySelector('.photo-poses'),count=el.querySelector('output'),thumb=el.querySelector('.photo-thumb'),retry=el.querySelector('.photo-retry');let active=false,busy=false,timer=false,token=0,pending=null;
 function exit(){token++;active=false;busy=false;count.textContent='';controls.hidden=true;poses.hidden=true;document.body.classList.remove('photo-mode');visual.photo(false);shutter.innerHTML=cameraIcon;shutter.setAttribute('aria-label','打开相机');shutter.disabled=false}
 function open(){active=true;visual.photo(true);document.body.classList.add('photo-mode');controls.hidden=false;shutter.innerHTML='<span></span>';shutter.setAttribute('aria-label','拍照')}
 async function save(){await photoRequest(cloud,{action:'save',...pending});pending=null;retry.hidden=true;toast('已收进相册')}
 async function shoot(){if(busy)return;if(pending){toast('先保存或下载刚才的照片');return}busy=true;shutter.disabled=true;const seq=++token;try{if(timer){for(let n=3;n>0;n--){count.textContent=n;await new Promise(r=>setTimeout(r,1000));if(seq!==token)return}count.textContent=''}const image=await visual.capture();pending={id:photoId(),image,room:visual.photoState().room};thumb.querySelector('img').src=image;thumb.hidden=false;retry.querySelector('a').href=image;document.body.classList.add('photo-flash');setTimeout(()=>document.body.classList.remove('photo-flash'),160);await save()}catch(e){retry.hidden=!pending;toast(e.message||'照片暂未保存，请重试')}finally{if(seq===token){busy=false;shutter.disabled=false}}}
 document.addEventListener('echoo-photo-exit',exit);shutter.onclick=()=>active?shoot():open();thumb.onclick=()=>{exit();onAlbum()};el.onclick=async e=>{const b=e.target.closest('[data-photo]'),pose=e.target.closest('[data-pose]');if(pose){if(visual.photoPose(pose.dataset.pose)){poses.hidden=true;el.querySelectorAll('[data-pose]').forEach(x=>x.classList.toggle('selected',x===pose))}else toast('先拍下此刻，空闲时再摆姿势');return}if(!b)return;const a=b.dataset.photo;if(a==='exit')exit();if(a==='timer'){timer=!timer;b.setAttribute('aria-pressed',timer)}if(a==='poses'){poses.hidden=!poses.hidden;el.querySelectorAll('[data-pose]').forEach(x=>x.disabled=x.dataset.pose!=='current'&&!visual.photoState().canPose)}if(a==='retry'&&!busy){busy=true;b.disabled=true;try{await save()}catch(e){toast(e.message)}finally{busy=false;b.disabled=false}}};document.addEventListener('keydown',e=>{if(!active)return;if(e.key==='Escape'){e.preventDefault();exit()}if(e.code==='Space'&&e.target===document.body){e.preventDefault();shoot()}});return {exit,get active(){return active}};
}
